import{_ as r,o,c as t,a2 as a}from"./chunks/framework.CLq81i8L.js";const u=JSON.parse('{"title":"Model Architecture","description":"","frontmatter":{"title":"Model Architecture"},"headers":[],"relativePath":"en/design/model-architecture.md","filePath":"en/design/model-architecture.md","lastUpdated":1785141086000}'),i={name:"en/design/model-architecture.md"};function n(s,e,l,d,p,c){return o(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="model-architecture" tabindex="-1">Model Architecture <a class="header-anchor" href="#model-architecture" aria-label="Permalink to &quot;Model Architecture&quot;">​</a></h1><p>Schema Platform uses a <strong>Provider/Model two-tier structure</strong> for flexible LLM management.</p><h2 id="provider-layer" tabindex="-1">Provider Layer <a class="header-anchor" href="#provider-layer" aria-label="Permalink to &quot;Provider Layer&quot;">​</a></h2><p>A Provider represents an LLM service endpoint:</p><ul><li><strong>Name</strong>: Display name (e.g., &quot;DeepSeek&quot;, &quot;OpenAI&quot;)</li><li><strong>Type</strong>: Provider type (deepseek, openai, anthropic, custom)</li><li><strong>Base URL</strong>: API endpoint</li><li><strong>API Key</strong>: Authentication key</li></ul><h2 id="model-layer" tabindex="-1">Model Layer <a class="header-anchor" href="#model-layer" aria-label="Permalink to &quot;Model Layer&quot;">​</a></h2><p>Models belong to a Provider:</p><ul><li><strong>Model ID</strong>: API model identifier (e.g., <code>deepseek-chat</code>)</li><li><strong>Capabilities</strong>: chat, vision, embedding</li><li><strong>Parameters</strong>: temperature, maxTokens, topP</li></ul><h2 id="priority-resolution" tabindex="-1">Priority Resolution <a class="header-anchor" href="#priority-resolution" aria-label="Permalink to &quot;Priority Resolution&quot;">​</a></h2><p>When the system needs an LLM:</p><ol><li><strong>User config</strong> (highest priority) — User&#39;s preferred model</li><li><strong>DB Provider+Model</strong> — Stored in MongoDB</li><li><strong>LLMManager</strong> — Built-in provider registry</li><li><strong>Environment variables</strong> (lowest priority) — <code>DEEPSEEK_API_KEY</code>, etc.</li></ol><h2 id="byok-bring-your-own-key" tabindex="-1">BYOK (Bring Your Own Key) <a class="header-anchor" href="#byok-bring-your-own-key" aria-label="Permalink to &quot;BYOK (Bring Your Own Key)&quot;">​</a></h2><p>Users can configure their own API keys in <strong>Settings → Models</strong>. Keys are stored encrypted in MongoDB and scoped to the user&#39;s tenant.</p><h2 id="openai-compatible-providers" tabindex="-1">OpenAI-Compatible Providers <a class="header-anchor" href="#openai-compatible-providers" aria-label="Permalink to &quot;OpenAI-Compatible Providers&quot;">​</a></h2><p>Any provider with an OpenAI-compatible API can be added as <code>type: custom</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Base URL: https://your-provider.com/v1</span></span>
<span class="line"><span>API Key: your-key</span></span>
<span class="line"><span>Model ID: your-model-id</span></span></code></pre></div><p>This covers Ollama, vLLM, DeepSeek, Moonshot, and many others.</p>`,17)])])}const g=r(i,[["render",n]]);export{u as __pageData,g as default};
